async function vtt(r,t=0){const s=await r.arrayBuffer(),a=EA(s,{type:"array"});let n=a.SheetNames.find(h=>h.includes("សិស្ស")||h.includes("ថ្នាក់"))||a.SheetNames[0];if(!n)return{students:[],meta:{}};const i=a.Sheets[n],csv=Gm.sheet_to_csv(i),parsed=zw(csv,t);if(parsed&&parsed.students&&parsed.students.length>0)return parsed;for(const other of a.SheetNames){if(other===n)continue;const otherCsv=Gm.sheet_to_csv(a.Sheets[other]),pOther=zw(otherCsv,t);if(pOther&&pOther.students&&pOther.students.length>0)return pOther}return{students:[],meta:{}}}
const XLSX = require("xlsx");
const fs = require("fs");
const buf = fs.readFileSync("public/បញ្ជីសិស្ស-ថ្នាក់6ក-សាលាបឋមសិក្សាហ៊ុនសែនអូរឫស្សីកណ្តាល.xlsx");
async function test() {
  try {
    const res = await vtt({ arrayBuffer: async () => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) }, 0);
    console.log("Parsed count:", res.students.length);
  } catch (e) {
    console.error("Error in test:", e);
  }
}
test();
